solution:
import re

def ping_cmd(host):
    if not re.fullmatch(r"[A-Za-z0-9.-]+", host):
        raise ValueError("bad host")
    return ["ping", "-c", "1", host]

alt:
import re

def ping_cmd(host):
    if re.match(r"^[A-Za-z0-9.\-]+$", host) is None:
        raise ValueError(host)
    return ["ping", "-c", "1", host]
